if (particleCount == 0)
        return nullptr;

    // Find the maximum hash value to determine the size of the neighbor table
    uint32_t maxHash = 0;
    for (size_t i = 0; i < particleCount; ++i)
    {
        if (sortedParticles[i].hash > maxHash)
            maxHash = sortedParticles[i].hash;
    }

    // Allocate the neighbor table
    uint32_t* neighborTable = new uint32_t[maxHash + 1];
    std::fill(neighborTable, neighborTable + maxHash + 1, UINT32_MAX);

    // Populate the neighbor table
    for (size_t i = 0; i < particleCount; ++i)
    {
        uint16_t currentHash = sortedParticles[i].hash;
        if (neighborTable[currentHash] == UINT32_MAX)
        {
            neighborTable[currentHash] = static_cast<uint32_t>(i);
        }
    }

    return neighborTable;
